function iconFor(kind: string) {
  const props = { size: 14, strokeWidth: 1.7 }
  if (kind === 'folder') return <Folder {...props} />
  if (kind === 'mesh' || kind === 'world') return <Boxes {...props} />
  if (kind === 'cube') return <Box {...props} />
  if (kind === 'landscape') return <Trees {...props} />
  if (kind === 'water') return <CircleDot {...props} />
  if (kind === 'sky' || kind === 'cloud') return <CloudSun {...props} />
  if (kind === 'light' || kind === 'sun') return <Lightbulb {...props} />
  if (kind === 'effects') return <Sparkles {...props} />
  return <Layers3 {...props} />
}

function useModulePreview(workspace: WorkspacePayload, module: AnalysisModule) {
  const [loaded, setLoaded] = useState({ path: '', source: '' })
  useEffect(() => {
    let active = true
    if (!module.previewPath || !window.kiana) return () => { active = false }
    void window.kiana.loadImage(module.previewPath).then(value => { if (active) setLoaded({ path: module.previewPath, source: value }) }).catch(() => { /* fall back to the real RDC thumbnail below */ })
    return () => { active = false }
  }, [workspace.capturePath, module.previewPath])
  return module.previewPath && loaded.path === module.previewPath && loaded.source ? loaded.source : previewSource(workspace)
}

function useCompositionPreview(workspace: WorkspacePayload, module: AnalysisModule, stage: CompositionStage | null) {
  const fallback = useModulePreview(workspace, module)
  const [loaded, setLoaded] = useState({ key: '', source: '' })
  const eventId = stage?.eventId || 0
  const resourceId = stage?.outputResourceIds[0] || 0
  const stageName = stage?.name || ''
  const key = stage ? `${workspace.capturePath}:${eventId}:${resourceId}` : ''
  useEffect(() => {
    let active = true
    if (!eventId || !resourceId || !window.kiana) return () => { active = false }
    void window.kiana.previewStage(eventId, resourceId, stageName).then(value => {
      if (active) setLoaded({ key, source: value.dataUrl })
    }).catch(() => { /* keep the capture thumbnail while the live RT export is unavailable */ })
    return () => { active = false }
  }, [key, eventId, resourceId, stageName])
  if (!stage) return fallback
  if (key && loaded.key === key && loaded.source) return loaded.source
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720"><rect width="100%" height="100%" fill="#02070b"/><text x="50%" y="48%" text-anchor="middle" fill="#77dcec" font-family="Segoe UI, sans-serif" font-size="24">正在锁定 EID ${stage.eventId}</text><text x="50%" y="54%" text-anchor="middle" fill="#59717d" font-family="Segoe UI, sans-serif" font-size="15">从 RenderDoc 导出该步骤的真实 RT</text></svg>`)
}

